import React, { useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { Eye, EyeOff, Lock, Mail, User } from "lucide-react";
import { useAuth } from "./AuthContext";
import { useTheme } from "./ThemeContext";
import { h, f } from "./h";
import { apiFetch } from "./api";
import { Button, Field, GlassPanel, LogoMark, RefImage, TextInput, ThemeToggleButton } from "./ui";

export function LoginPage() {
  const nav = useNavigate();
  const { login } = useAuth();
  const { dark, toggle } = useTheme();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await login(email.trim(), password);
      nav("/shop", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Login failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "relative min-h-screen overflow-hidden" }, [
    h(RefImage, {
      n: 17,
      alt: "",
      className: "pointer-events-none absolute inset-0 h-full w-full object-cover opacity-40 dark:opacity-25"
    }),
    h("div", {
      className:
        "absolute inset-0 bg-gradient-to-b from-slate-100/90 via-slate-100/80 to-slate-200/90 dark:from-night-950/95 dark:via-night-950/90 dark:to-slate-950/95"
    }),
    h(
      "div",
      { className: "relative z-10 mx-auto flex min-h-screen max-w-lg flex-col px-4 py-8 sm:px-6" },
      [
        h(
          "div",
          { className: "mb-6 flex items-center justify-between" },
          h(Link, { to: "/shop", className: "flex items-center gap-2" }, [
            h(LogoMark),
            h(
              "span",
              { className: "font-display text-xl font-semibold text-slate-900 dark:text-white" },
              "BrewMart"
            )
          ]),
          h(ThemeToggleButton, { dark, onToggle: toggle })
        ),
        h(GlassPanel, { className: "mx-auto w-full max-w-md" }, [
          h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Welcome back"),
          h("p", { className: "mt-1 text-sm text-slate-600 dark:text-slate-400" }, "Sign in to continue shopping."),
          h(
            "form",
            { className: "mt-6 space-y-4", onSubmit },
            [
              h(Field, { label: "Email" }, h(TextInput, {
                type: "email",
                autoComplete: "email",
                value: email,
                onChange: (e) => setEmail(e.target.value),
                placeholder: "you@email.com",
                required: true
              })),
              h(Field, { label: "Password" }, h("div", { className: "relative" }, [
                h(TextInput, {
                  type: show ? "text" : "password",
                  autoComplete: "current-password",
                  value: password,
                  onChange: (e) => setPassword(e.target.value),
                  placeholder: "••••••••",
                  className: "pr-12",
                  required: true
                }),
                h(
                  "button",
                  {
                    type: "button",
                    className:
                      "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:text-slate-400 dark:hover:bg-white/10",
                    onClick: () => setShow((s) => !s)
                  },
                  show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                )
              ])),
              err && h("p", { className: "text-sm text-rose-400" }, err),
              h(Button, { type: "submit", className: "w-full", loading }, "Sign in"),
              h(
                "div",
                { className: "flex flex-wrap justify-between gap-2 text-sm" },
                h(Link, { to: "/forgot-password", className: "text-sky-600 hover:underline dark:text-sky-300" }, "Forgot password?"),
                h(Link, { to: "/register", className: "text-sky-600 hover:underline dark:text-sky-300" }, "Create account")
              )
            ]
          )
        ])
      ]
    )
  ]);
}

export function RegisterPage() {
  const nav = useNavigate();
  const { register } = useAuth();
  const { dark, toggle } = useTheme();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [show, setShow] = useState(false);
  const [role, setRole] = useState("buyer");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await register({ email: email.trim(), password, role });
      nav("/verify-email", { state: { email: email.trim(), name }, replace: true });
    } catch (ex) {
      setErr(ex.message || "Registration failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "relative min-h-screen overflow-hidden" }, [
    h(RefImage, {
      n: 18,
      alt: "",
      className: "pointer-events-none absolute inset-0 h-full w-full object-cover opacity-35 dark:opacity-20"
    }),
    h("div", {
      className:
        "absolute inset-0 bg-gradient-to-b from-amber-50/90 via-slate-100/85 to-slate-200/90 dark:from-night-950/95 dark:via-night-950/90 dark:to-slate-950/95"
    }),
    h(
      "div",
      { className: "relative z-10 mx-auto flex min-h-screen max-w-lg flex-col px-4 py-8 sm:px-6" },
      [
        h(
          "div",
          { className: "mb-6 flex items-center justify-between" },
          h(Link, { to: "/shop", className: "flex items-center gap-2" }, [
            h(LogoMark),
            h("span", { className: "font-display text-xl font-semibold text-slate-900 dark:text-white" }, "BrewMart")
          ]),
          h(ThemeToggleButton, { dark, onToggle: toggle })
        ),
        h(GlassPanel, { className: "mx-auto w-full max-w-md" }, [
          h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Join us"),
          h("p", { className: "mt-1 text-sm text-slate-600 dark:text-slate-400" }, "Create your account to get started."),
          h(
            "form",
            { className: "mt-6 space-y-4", onSubmit },
            [
              h(Field, { label: h("span", { className: "inline-flex items-center gap-1" }, [h(User, { className: "h-3.5 w-3.5" }), " Full name"]) }, h(TextInput, {
                value: name,
                onChange: (e) => setName(e.target.value),
                placeholder: "John Doe",
                autoComplete: "name"
              })),
              h(Field, { label: h("span", { className: "inline-flex items-center gap-1" }, [h(Mail, { className: "h-3.5 w-3.5" }), " Email"]) }, h(TextInput, {
                type: "email",
                value: email,
                onChange: (e) => setEmail(e.target.value),
                placeholder: "your@email.com",
                required: true,
                autoComplete: "email"
              })),
              h(Field, {
                label: h("span", { className: "inline-flex items-center gap-1" }, [h(Lock, { className: "h-3.5 w-3.5" }), " Password"])
              }, [
                h("div", { className: "relative" }, [
                  h(TextInput, {
                    type: show ? "text" : "password",
                    value: password,
                    onChange: (e) => setPassword(e.target.value),
                    placeholder: "••••••••",
                    className: "pr-12",
                    required: true,
                    autoComplete: "new-password",
                    minLength: 8
                  }),
                  h(
                    "button",
                    {
                      type: "button",
                      className:
                        "tap-target absolute right-1 top-1/2 -translate-y-1/2 rounded-xl p-2 text-slate-500 hover:bg-white/40 dark:text-slate-400 dark:hover:bg-white/10",
                      onClick: () => setShow((s) => !s)
                    },
                    show ? h(EyeOff, { className: "h-5 w-5" }) : h(Eye, { className: "h-5 w-5" })
                  )
                ]),
                h(
                  "p",
                  { className: "text-xs text-slate-500 dark:text-slate-400" },
                  "8+ characters with upper, lower, number, and a symbol."
                )
              ]),
              h("div", { className: "space-y-2" }, [
                h("p", { className: "text-xs font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400" }, "I am a…"),
                h("div", { className: "grid grid-cols-2 gap-2 sm:gap-3" }, [
                  h(
                    "button",
                    {
                      type: "button",
                      onClick: () => setRole("buyer"),
                      className: `tap-target rounded-2xl border px-3 py-3 text-sm font-medium transition sm:text-base ${
                        role === "buyer"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "Student (Buyer)"
                  ),
                  h(
                    "button",
                    {
                      type: "button",
                      onClick: () => setRole("seller"),
                      className: `tap-target rounded-2xl border px-3 py-3 text-sm font-medium transition sm:text-base ${
                        role === "seller"
                          ? "border-sky-500/60 bg-sky-500/15 text-slate-900 dark:border-sky-400/50 dark:text-white"
                          : "border-slate-300/70 bg-white/30 text-slate-700 hover:bg-white/50 dark:border-white/10 dark:bg-white/5 dark:text-slate-200 dark:hover:bg-white/10"
                      }`
                    },
                    "Vendor (Seller)"
                  )
                ])
              ]),
              err && h("p", { className: "text-sm text-rose-400" }, err),
              h(Button, { type: "submit", className: "w-full", loading }, "Create account"),
              h(
                "p",
                { className: "text-center text-sm text-slate-600 dark:text-slate-400" },
                "Already have an account? ",
                h(Link, { to: "/login", className: "font-semibold text-sky-600 hover:underline dark:text-sky-300" }, "Login")
              )
            ]
          )
        ])
      ]
    )
  ]);
}

export function VerifyEmailPage() {
  const nav = useNavigate();
  const loc = useLocation();
  const email = loc.state?.email || "";
  const [token, setToken] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/verify-email", { method: "POST", json: { token: token.trim() } });
      nav("/login", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Verification failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, h(GlassPanel, {}, [
    h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Verify email"),
    h("p", { className: "mt-2 text-sm text-slate-600 dark:text-slate-400" }, `We sent a token to ${email || "your inbox"}. Paste it below.`),
    h(
      "form",
      { className: "mt-6 space-y-4", onSubmit },
      [
        h(Field, { label: "Verification token" }, h(TextInput, { value: token, onChange: (e) => setToken(e.target.value), required: true })),
        err && h("p", { className: "text-sm text-rose-400" }, err),
        h(Button, { type: "submit", className: "w-full", loading }, "Verify"),
        h(Link, { to: "/login", className: "block text-center text-sm text-sky-600 hover:underline dark:text-sky-300" }, "Back to login")
      ]
    )
  ]));
}

export function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setMsg("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/forgot-password", { method: "POST", json: { email: email.trim() } });
      setMsg("If that email exists, a reset token was sent.");
    } catch (ex) {
      setErr(ex.message || "Request failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, h(GlassPanel, {}, [
    h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "Reset password"),
    h("form", { className: "mt-6 space-y-4", onSubmit }, [
      h(Field, { label: "Email" }, h(TextInput, { type: "email", value: email, onChange: (e) => setEmail(e.target.value), required: true })),
      msg && h("p", { className: "text-sm text-emerald-400" }, msg),
      err && h("p", { className: "text-sm text-rose-400" }, err),
      h(Button, { type: "submit", className: "w-full", loading }, "Send token"),
      h(Link, { to: "/login", className: "block text-center text-sm text-sky-600 hover:underline dark:text-sky-300" }, "Back to login")
    ])
  ]));
}

export function ResetPasswordPage() {
  const [token, setToken] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [err, setErr] = useState("");
  const [loading, setLoading] = useState(false);
  const nav = useNavigate();

  const onSubmit = async (e) => {
    e.preventDefault();
    setErr("");
    setLoading(true);
    try {
      await apiFetch("/api/auth/reset-password", {
        method: "POST",
        json: { token: token.trim(), newPassword }
      });
      nav("/login", { replace: true });
    } catch (ex) {
      setErr(ex.message || "Reset failed");
    } finally {
      setLoading(false);
    }
  };

  return h("div", { className: "mx-auto max-w-md px-4 py-16" }, h(GlassPanel, {}, [
    h("h1", { className: "font-display text-2xl font-bold text-slate-900 dark:text-white" }, "New password"),
    h("form", { className: "mt-6 space-y-4", onSubmit }, [
      h(Field, { label: "Reset token" }, h(TextInput, { value: token, onChange: (e) => setToken(e.target.value), required: true })),
      h(Field, { label: "New password" }, h(TextInput, { type: "password", value: newPassword, onChange: (e) => setNewPassword(e.target.value), required: true, minLength: 8 })),
      err && h("p", { className: "text-sm text-rose-400" }, err),
      h(Button, { type: "submit", className: "w-full", loading }, "Update password")
    ])
  ]));
}
